DECLARE
  list_owner_user_id UUID;
BEGIN
  -- Check if the current user owns the list
  SELECT p.user_id INTO list_owner_user_id
  FROM lists l
  JOIN profiles p ON p.id = l.owner_id
  WHERE l.id = list_id_param;

  IF list_owner_user_id != auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: You can only add studios to your own lists';
  END IF;

  -- Insert or update the list item (upsert)
  INSERT INTO list_items (list_id, studio_id, notes)
  VALUES (list_id_param, studio_id_param, notes_param)
  ON CONFLICT (list_id, studio_id) 
  DO UPDATE SET 
    notes = COALESCE(notes_param, list_items.notes),
    created_at = NOW();

  RETURN TRUE;
END;

DECLARE
  current_profile_id BIGINT;
BEGIN
  -- Get current user's profile ID
  SELECT id INTO current_profile_id 
  FROM profiles 
  WHERE user_id = auth.uid();

  IF current_profile_id IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  -- Verify studio exists and is unclaimed
  IF NOT EXISTS (
    SELECT 1 FROM studios 
    WHERE id = studio_id_param 
    AND verification_status = 'unclaimed'
  ) THEN
    RAISE EXCEPTION 'Studio not found or already claimed';
  END IF;

  -- Update studio with claim information
  UPDATE studios 
  SET 
    verification_status = 'pending_claim_verification',
    claimed_by = current_profile_id,
    verification_documents = verification_docs,
    updated_at = NOW()
  WHERE id = studio_id_param;

END;

DECLARE
  conversation_id BIGINT;
  customer_profile_id BIGINT;
  studio_owner_profile_id BIGINT;
  current_profile_id BIGINT;
BEGIN
  -- Get current user's profile ID
  SELECT id INTO current_profile_id
  FROM profiles 
  WHERE user_id = auth.uid();

  IF current_profile_id IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  -- Get customer profile ID from inquiry
  SELECT creator_id INTO customer_profile_id
  FROM inquiries
  WHERE id = inquiry_id_param;

  IF customer_profile_id IS NULL THEN
    RAISE EXCEPTION 'Inquiry not found';
  END IF;

  -- Get studio owner profile ID
  SELECT owner_id INTO studio_owner_profile_id
  FROM studios
  WHERE id = studio_id_param;

  IF studio_owner_profile_id IS NULL THEN
    RAISE EXCEPTION 'Studio owner not found';
  END IF;

  -- Verify the current user is either the customer or studio owner
  IF current_profile_id != customer_profile_id AND current_profile_id != studio_owner_profile_id THEN
    RAISE EXCEPTION 'Unauthorized to create conversation for this inquiry';
  END IF;

  -- Check if conversation already exists
  SELECT id INTO conversation_id
  FROM conversations
  WHERE inquiry_id = inquiry_id_param 
    AND studio_id = studio_id_param;

  -- Create conversation if it doesn't exist
  IF conversation_id IS NULL THEN
    INSERT INTO conversations (
      inquiry_id,
      customer_id,
      studio_owner_id,
      studio_id,
      status
    ) VALUES (
      inquiry_id_param,
      customer_profile_id,
      studio_owner_profile_id,
      studio_id_param,
      'active'
    ) RETURNING id INTO conversation_id;
  END IF;

  -- Add initial message if provided
  IF initial_message IS NOT NULL AND initial_message != '' THEN
    INSERT INTO messages (
      conversation_id,
      sender_id,
      content,
      message_type
    ) VALUES (
      conversation_id,
      current_profile_id,
      initial_message,
      'text'
    );
  END IF;

  RETURN conversation_id;
END;

