DECLARE
  result JSON;
  conversation_count INTEGER;
  booking_count INTEGER;
  message_count INTEGER;
BEGIN
  -- Check if studio exists
  IF NOT EXISTS (SELECT 1 FROM studios WHERE id = studio_id_param) THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Studio not found'
    );
  END IF;

  -- Count related records for reporting
  SELECT COUNT(*) INTO conversation_count FROM conversations WHERE studio_id = studio_id_param;
  SELECT COUNT(*) INTO booking_count FROM bookings WHERE studio_id = studio_id_param;
  SELECT COUNT(*) INTO message_count FROM messages 
    WHERE conversation_id IN (SELECT id FROM conversations WHERE studio_id = studio_id_param);

  -- Start transaction for safe deletion
  BEGIN
    -- 1. Delete messages related to studio conversations
    DELETE FROM messages 
    WHERE conversation_id IN (SELECT id FROM conversations WHERE studio_id = studio_id_param);

    -- 2. Delete conversation participants
    DELETE FROM conversation_participants 
    WHERE conversation_id IN (SELECT id FROM conversations WHERE studio_id = studio_id_param);

    -- 3. Delete conversations
    DELETE FROM conversations WHERE studio_id = studio_id_param;

    -- 4. Delete booking add-ons for studio bookings
    DELETE FROM booking_add_ons 
    WHERE booking_id IN (SELECT id FROM bookings WHERE studio_id = studio_id_param);

    -- 5. Delete reviews for studio bookings  
    DELETE FROM reviews 
    WHERE booking_id IN (SELECT id FROM bookings WHERE studio_id = studio_id_param);

    -- 6. Delete dispute messages for studio booking disputes
    DELETE FROM dispute_messages 
    WHERE dispute_id IN (
      SELECT id FROM disputes 
      WHERE booking_id IN (SELECT id FROM bookings WHERE studio_id = studio_id_param)
    );

    -- 7. Delete disputes for studio bookings
    DELETE FROM disputes 
    WHERE booking_id IN (SELECT id FROM bookings WHERE studio_id = studio_id_param);

    -- 8. Delete bookings
    DELETE FROM bookings WHERE studio_id = studio_id_param;

    -- 9. Delete inquiry recipients
    DELETE FROM inquiry_recipients WHERE studio_id = studio_id_param;

    -- 10. Delete favorites
    DELETE FROM favorites WHERE studio_id = studio_id_param;

    -- 11. Delete pricing rules
    DELETE FROM pricing_rules WHERE studio_id = studio_id_param;

    -- 12. Delete add-on services  
    DELETE FROM add_on_services WHERE studio_id = studio_id_param;

    -- 13. Delete studio amenities
    DELETE FROM studio_amenities WHERE studio_id = studio_id_param;

    -- 14. Finally, delete the studio itself
    DELETE FROM studios WHERE id = studio_id_param;

    -- Return success with cleanup stats
    RETURN json_build_object(
      'success', true,
      'deleted_studio_id', studio_id_param,
      'cleanup_stats', json_build_object(
        'conversations_deleted', conversation_count,
        'bookings_deleted', booking_count,
        'messages_deleted', message_count
      )
    );

  EXCEPTION
    WHEN OTHERS THEN
      -- Rollback happens automatically
      RETURN json_build_object(
        'success', false,
        'error', 'Failed to delete studio: ' || SQLERRM
      );
  END;
END;

