DECLARE
  conversation_id_result BIGINT;
  creator_profile_id BIGINT;
  studio_owner_profile_id BIGINT;
  message_type_to_use TEXT;
BEGIN
  -- Get creator and studio owner profile IDs
  SELECT i.creator_id, s.owner_id 
  INTO creator_profile_id, studio_owner_profile_id
  FROM inquiries i
  JOIN studios s ON s.id = studio_id_param
  WHERE i.id = inquiry_id_param;

  -- Find existing conversation or create new one
  SELECT c.id INTO conversation_id_result
  FROM conversations c
  WHERE c.inquiry_id = inquiry_id_param 
  AND c.studio_id = studio_id_param;

  IF conversation_id_result IS NULL THEN
    -- Create new conversation
    INSERT INTO conversations (inquiry_id, studio_id, customer_id, studio_owner_id)
    VALUES (inquiry_id_param, studio_id_param, creator_profile_id, studio_owner_profile_id)
    RETURNING id INTO conversation_id_result;

    -- Add participants
    INSERT INTO conversation_participants (conversation_id, profile_id)
    VALUES 
      (conversation_id_result, creator_profile_id),
      (conversation_id_result, studio_owner_profile_id);
  END IF;

  -- Determine message type based on whether quote amount is provided
  IF quote_amount_param IS NOT NULL AND quote_amount_param > 0 THEN
    message_type_to_use := 'quote';
  ELSE
    message_type_to_use := 'text';
  END IF;

  -- Insert message with appropriate type
  INSERT INTO messages (
    conversation_id, 
    sender_id, 
    content, 
    message_type, 
    quote_amount
  ) VALUES (
    conversation_id_result,
    studio_owner_profile_id,
    response_message_param,
    message_type_to_use,
    CASE WHEN message_type_to_use = 'quote' THEN quote_amount_param ELSE NULL END
  );

  -- Update inquiry_recipients status
  UPDATE inquiry_recipients 
  SET status = 'responded', 
      response_message = response_message_param,
      quote_amount = quote_amount_param,
      responded_at = NOW()
  WHERE inquiry_id = inquiry_id_param 
  AND studio_id = studio_id_param;

  -- Update conversation last_message_at
  UPDATE conversations 
  SET last_message_at = NOW()
  WHERE id = conversation_id_result;

  RETURN conversation_id_result;
END;

DECLARE
  sanitized_username TEXT;
  base_username TEXT;
  counter INTEGER := 0;
  final_username TEXT;
BEGIN
  -- Create a sanitized username from email or metadata
  base_username := COALESCE(
    NEW.raw_user_meta_data->>'username',
    NEW.raw_user_meta_data->>'name'
  );

  -- If no username in metadata, sanitize the email
  IF base_username IS NULL AND NEW.email IS NOT NULL THEN
    -- Extract username part from email (before @)
    base_username := split_part(NEW.email, '@', 1);

    -- Remove dots, hyphens, and other invalid characters
    base_username := regexp_replace(base_username, '[^a-zA-Z0-9_]', '_', 'g');

    -- Replace multiple underscores with single underscore
    base_username := regexp_replace(base_username, '_+', '_', 'g');

    -- Remove leading/trailing underscores
    base_username := trim(base_username, '_');

    -- Convert to lowercase
    base_username := lower(base_username);

    -- Ensure minimum length of 3 characters
    IF length(base_username) < 3 THEN
      base_username := base_username || '_user';
    END IF;
  END IF;

  -- Final fallback if still no valid username
  IF base_username IS NULL OR length(base_username) < 3 THEN
    base_username := 'user_' || substr(NEW.id::text, 1, 8);
  END IF;

  -- Ensure username is unique by adding numbers if needed
  sanitized_username := base_username;

  -- Check if username exists and increment counter if needed
  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE username = sanitized_username) LOOP
    counter := counter + 1;
    sanitized_username := base_username || '_' || counter;
  END LOOP;

  final_username := sanitized_username;

  INSERT INTO public.profiles (user_id, role, created_at, updated_at, username)
  VALUES (
    NEW.id,
    NULL, -- Role is NULL initially to trigger onboarding
    NOW(),
    NOW(),
    final_username
  );
  RETURN NEW;
EXCEPTION
  WHEN unique_violation THEN
    -- Profile already exists, ignore
    RETURN NEW;
  WHEN OTHERS THEN
    -- Log error but don't break auth flow
    RAISE LOG 'Error in handle_new_user: %', SQLERRM;
    RETURN NEW;
END;

