  SELECT id INTO current_profile_id
  FROM profiles 
  WHERE user_id = auth.uid();

  IF current_profile_id IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  -- Verify user is part of the conversation
  IF NOT EXISTS (
    SELECT 1 FROM conversations
    WHERE id = conversation_id_param 
      AND (customer_id = current_profile_id OR studio_owner_id = current_profile_id)
  ) THEN
    RAISE EXCEPTION 'Unauthorized to mark messages as read in this conversation';
  END IF;

  -- Mark all unread messages from other participants as read
  UPDATE messages 
  SET read_at = NOW()
  WHERE conversation_id = conversation_id_param 
    AND sender_id != current_profile_id 
    AND read_at IS NULL;
END;

DECLARE
  list_owner_user_id UUID;
BEGIN
  -- Check if the current user owns the list
  SELECT p.user_id INTO list_owner_user_id
  FROM lists l
  JOIN profiles p ON p.id = l.owner_id
  WHERE l.id = list_id_param;

  IF list_owner_user_id != auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: You can only remove studios from your own lists';
  END IF;

  -- Remove the studio from the list
  DELETE FROM list_items 
  WHERE list_id = list_id_param AND studio_id = studio_id_param;

  RETURN TRUE;
END;

DECLARE
  message_id BIGINT;
  current_profile_id BIGINT;
BEGIN
  -- Get current user's profile ID
  SELECT id INTO current_profile_id
  FROM profiles 
  WHERE user_id = auth.uid();

  IF current_profile_id IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  -- Verify user is part of the conversation
  IF NOT EXISTS (
    SELECT 1 FROM conversations
    WHERE id = conversation_id_param 
      AND (customer_id = current_profile_id OR studio_owner_id = current_profile_id)
  ) THEN
    RAISE EXCEPTION 'Unauthorized to send message in this conversation';
  END IF;

  -- Insert message
  INSERT INTO messages (
    conversation_id,
    sender_id,
    content,
    message_type,
    quote_amount,
    file_url,
    file_name,
    file_size
  ) VALUES (
    conversation_id_param,
    current_profile_id,
    content_param,
    message_type_param,
    quote_amount_param,
    file_url_param,
    file_name_param,
    file_size_param
  ) RETURNING id INTO message_id;

  RETURN message_id;
END;

